#!/usr/bin/env python3
"""Write docs/licenses/TEXLIB_CREDITS.md: one row per shortlisted material (source, page, licence, hash)."""
import json
from pathlib import Path

HERE = Path(__file__).parent
cat = [e for e in json.load(open(HERE / "catalog.json")) if e["tier"] == "shortlist"]
out = ["# Texture library credits (shortlist)", "",
       "Generated by `tools/newdawn/texlib/credits.py` from `catalog.json`. Source licence evidence is in `docs/licenses/texlib/`.",
       "The image files are not yet committed; each row is what the engine may pick for the base library (ND-016).", "",
       "- **ambientCG**: CC0 1.0, https://ambientcg.com/ (credit not required; given anyway).",
       "- **Poly Haven**: CC0, https://polyhaven.com/ (credit not required; given anyway).",
       "- **TextureCan**: CC0 1.0, https://www.texturecan.com/.",
       "- **AMD GPUOpen MaterialX Library**: MIT. *Copyright AMD. Permission is hereby granted, free of charge, to any person obtaining a copy of this material ... "
       "The above copyright notice and this permission notice shall be included in all copies or substantial portions.* Full text: `docs/licenses/texlib/gpuopen-mit.txt`.",
       "", "| Asset | Source | Class | Regions | Licence | Page | SHA-256 (of its 2K files) |", "|---|---|---|---|---|---|---|"]
for e in sorted(cat, key=lambda e: (e["class"], e["source"], e["id"])):
    out.append(f"| {e['id']} | {e['source']} | {e['class']} | {', '.join(e['regions'])} | {e['license']} | {e['page']} | `{(e.get('sha256') or 'unpinned')[:16]}` |")
(HERE.parents[2] / "docs/licenses/TEXLIB_CREDITS.md").write_text("\n".join(out) + "\n")
print(len(cat), "rows")

# coverage matrix (class x region) for candidate+shortlist
import collections
allc = [e for e in json.load(open(HERE / "catalog.json")) if e["tier"] in ("candidate", "shortlist")]
regs = ["clock_town", "termina_field", "swamp_woodfall", "snowhead", "great_bay", "ikana_tower", "interiors", "dungeon"]
L = ["# Candidate coverage (candidate + shortlist; one material can serve several regions)", "",
     "| class | total | shortlist | " + " | ".join(regs) + " |", "|---|---|---|" + "---|" * len(regs)]
for k in sorted({e["class"] for e in allc}):
    es = [e for e in allc if e["class"] == k]
    L.append(f"| {k} | {len(es)} | {sum(e['tier'] == 'shortlist' for e in es)} | " + " | ".join(str(sum(r in e["regions"] for e in es)) for r in regs) + " |")
L.append(f"| **all** | {len(allc)} | {len(cat)} | " + " | ".join(str(sum(r in e["regions"] for e in allc)) for r in regs) + " |")
L += ["", "Shortlist per region: " + ", ".join(f"{r} {sum(r in e['regions'] for e in cat)}" for r in regs),
      "Candidates by source: " + str(dict(collections.Counter(e["source"] for e in allc)))]
(HERE / "COVERAGE.md").write_text("\n".join(L) + "\n")
